import{_ as t,a as n,o as a,a4 as d}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse('{"title":"Get Admin Menu","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-menu","title":"Get Admin Menu","description":"Returns the admin sidebar as a permission-filtered nested tree for the authenticated token.","query":"curl -X GET \\"https://your-domain.com/api/admin/menu\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"[\\n  {\\n    \\"id\\": \\"menu\\",\\n    \\"tree\\": [\\n      {\\n        \\"key\\": \\"dashboard\\",\\n        \\"label\\": \\"Dashboard\\",\\n        \\"icon\\": \\"icon-dashboard\\",\\n        \\"sort\\": 1,\\n        \\"permission\\": \\"dashboard\\",\\n        \\"apiResource\\": { \\"rest\\": \\"/api/admin/dashboard/stats\\", \\"graphql\\": \\"statsAdminDashboard\\" },\\n        \\"children\\": []\\n      },\\n      {\\n        \\"key\\": \\"sales\\",\\n        \\"label\\": \\"Sales\\",\\n        \\"icon\\": \\"icon-sales\\",\\n        \\"sort\\": 2,\\n        \\"permission\\": \\"sales\\",\\n        \\"apiResource\\": null,\\n        \\"children\\": [\\n          {\\n            \\"key\\": \\"sales.orders\\",\\n            \\"label\\": \\"Orders\\",\\n            \\"icon\\": null,\\n            \\"sort\\": 1,\\n            \\"permission\\": \\"sales.orders\\",\\n            \\"apiResource\\": { \\"rest\\": \\"/api/admin/orders\\", \\"graphql\\": \\"adminOrders\\" },\\n            \\"children\\": []\\n          },\\n          {\\n            \\"key\\": \\"sales.shipments\\",\\n            \\"label\\": \\"Shipments\\",\\n            \\"icon\\": null,\\n            \\"sort\\": 2,\\n            \\"permission\\": \\"sales.shipments\\",\\n            \\"apiResource\\": { \\"rest\\": \\"/api/admin/shipments\\", \\"graphql\\": \\"adminShipments\\" },\\n            \\"children\\": []\\n          }\\n        ]\\n      },\\n      {\\n        \\"key\\": \\"catalog\\",\\n        \\"label\\": \\"Catalog\\",\\n        \\"icon\\": \\"icon-catalog\\",\\n        \\"sort\\": 3,\\n        \\"permission\\": \\"catalog\\",\\n        \\"apiResource\\": null,\\n        \\"children\\": [\\n          {\\n            \\"key\\": \\"catalog.products\\",\\n            \\"label\\": \\"Products\\",\\n            \\"icon\\": null,\\n            \\"sort\\": 1,\\n            \\"permission\\": \\"catalog.products\\",\\n            \\"apiResource\\": { \\"rest\\": \\"/api/admin/catalog/products\\", \\"graphql\\": \\"adminCatalogProducts\\" },\\n            \\"children\\": []\\n          }\\n        ]\\n      }\\n    ]\\n  }\\n]\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/navigation/menu.md","filePath":"api/rest-api/admin/navigation/menu.md","lastUpdated":1783079210000}'),r={name:"api/rest-api/admin/navigation/menu.md"};function i(o,e,s,l,c,h){return a(),n("div",null,e[0]||(e[0]=[d('<h1 id="get-admin-menu" tabindex="-1">Get Admin Menu <a class="header-anchor" href="#get-admin-menu" aria-label="Permalink to &quot;Get Admin Menu&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/menu</code></td><td>GET</td></tr></tbody></table><p>Returns the admin sidebar as a nested tree, filtered to what the authenticated token&#39;s role is allowed to see. Use it to build a back-office navigation/sidebar dynamically and to discover which API endpoint backs each screen.</p><p>The response is a one-element array. The single element wraps the navigation under <code>tree</code> — a nested array of menu nodes.</p><h2 id="permission-filtering" tabindex="-1">Permission Filtering <a class="header-anchor" href="#permission-filtering" aria-label="Permalink to &quot;Permission Filtering&quot;">​</a></h2><p>The tree is scoped to the token&#39;s role:</p><ul><li>A token whose permission type is <code>all</code> sees every menu node.</li><li>A token with custom permissions sees only the nodes its role permits; menus it cannot access are omitted entirely.</li></ul><p>So two admins with different roles will receive different trees from the same endpoint.</p><h2 id="response-fields" tabindex="-1">Response Fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response Fields&quot;">​</a></h2><p>Each node in <code>tree</code> (and in any nested <code>children</code>) has the shape:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>key</code></td><td>string</td><td>Unique node identifier (e.g. <code>sales.orders</code>).</td></tr><tr><td><code>label</code></td><td>string</td><td>Human-readable menu title.</td></tr><tr><td><code>icon</code></td><td>string | null</td><td>Icon class for top-level menus; <code>null</code> for sub-items.</td></tr><tr><td><code>sort</code></td><td>integer</td><td>Display order among its siblings.</td></tr><tr><td><code>permission</code></td><td>string</td><td>ACL key controlling visibility of this node.</td></tr><tr><td><code>apiResource</code></td><td>object | null</td><td>Maps the menu entry to its API endpoint, or <code>null</code>.</td></tr><tr><td><code>children</code></td><td>array</td><td>Nested child nodes (empty array when there are none).</td></tr></tbody></table><p>When present, <code>apiResource</code> carries:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>rest</code></td><td>string</td><td>The REST endpoint backing this screen.</td></tr><tr><td><code>graphql</code></td><td>string</td><td>The GraphQL operation backing this screen.</td></tr></tbody></table><p><code>apiResource</code> is <code>null</code> for group headers (parent menus that only contain children, such as <code>Sales</code> or <code>Catalog</code>) and for panel-only screens that have no API counterpart (such as Integration).</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>A request without a valid token returns <code>401 Unauthorized</code>.</p><p>All admin endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',17)]))}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
